&lt;h2 id=&#34;encoder-decoder-structure&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#encoder-decoder-structure&#34;&gt;#&lt;/a&gt; Encoder-Decoder Structure&lt;/h2&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/picture/CS/information_measure/encoder-decoder-structure.png&#34; alt=&#34;encoder-decoder&#34;&gt;&lt;/p&gt;
&lt;p&gt;&amp;#x672C;&amp;#x6587;&amp;#x7684;PartA &amp;#x65E8;&amp;#x5728;&amp;#x7814;&amp;#x7A76;&amp;#x5177;&amp;#x6709;IS&amp;#x7279;&amp;#x6027;&amp;#x7684;&amp;#x9690;&amp;#x7A7A;&amp;#x95F4;&amp;#x65F6;&amp;#xFF0C;Encoding-Decoding &amp;#x7684;&amp;#x51FD;&amp;#x6570;&amp;#x7279;&amp;#x5F81;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Definition 2&lt;/strong&gt;&lt;br&gt;
